const out = await Promise.all(ps.map(async ([k,cmd]) => ({k, r: await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000})})));
